import{prepareLazyGym5 as prepareGym5,prepareLazyPrologue as preparePrologue,prepareLazyForest as preparePrologueForest,prepareLazyCoast as preparePrologueCoast}from'./lazy-old-scenes-r3.mjs';
import{loadLazyJungle as loadJungle}from'./lazy-jungle-r3.mjs';import{loadLazyHubResources as loadHubResources}from'./lazy-hub-resources.mjs';
export async function loadResources({signal}={}){let jungle,hub,prologue,forest,coast,gym;try{jungle=await loadJungle({signal});hub=await loadHubResources({signal});prologue=await preparePrologue({signal});forest=await preparePrologueForest({signal});coast=await preparePrologueCoast({signal});gym=await prepareGym5({signal});let disposed=false;return{...jungle,jungle,hub,prologue,forest,coast,gym,verificationScope:'FIVE_OLD_SCENE_CLOSURES_ONLY',get supportPinsVerified(){return!disposed&&jungle.supportPinsVerified&&hub.pinsVerified&&prologue.supportPinsVerified&&forest.supportPinsVerified&&coast.supportPinsVerified&&gym.supportPinsVerified},get allDeclaredBytesVerified(){return!disposed&&[jungle,prologue,forest,coast,gym].every(p=>p.allDeclaredBytesVerified)},get pinsVerified(){return!disposed&&jungle.pinsVerified&&hub.pinsVerified&&prologue.pinsVerified&&forest.pinsVerified&&coast.pinsVerified&&gym.pinsVerified},dispose(){if(disposed)return;disposed=true;let first;for(const resource of[gym,coast,forest,prologue,hub,jungle])try{resource?.dispose()}catch(e){first??=e}if(first)throw first}}}catch(e){for(const resource of[gym,coast,forest,prologue,hub,jungle])try{resource?.dispose()}catch{}throw e}}
